Un árbol de carpetas: cada carpeta tiene `sub` con sus subcarpetas. Para listar los nombres por profundidad:

function nombresPorProfundidad(carpeta) {
  if (!carpeta) return [];
  const resultado = [];
  let actual = [carpeta];
  while (actual.length > 0) {
    resultado.push(actual.map((c) => c.nombre));
    actual = actual.flatMap((c) => c.sub);
  }
  return resultado;
}
